CREATE POLICY internet_private_documents_service_read ON storage.objects FOR SELECT TO service_role USING (bucket_id='internet-invoices-private'); CREATE POLICY internet_private_documents_service_insert ON storage.objects FOR INSERT TO service_role WITH CHECK (bucket_id='internet-invoices-private'); CREATE POLICY internet_private_documents_service_update ON storage.objects FOR UPDATE TO service_role USING (bucket_id='internet-invoices-private') WITH CHECK (bucket_id='internet-invoices-private');
REVOKE SELECT ON public.internet_provider_accounts FROM authenticated;
GRANT SELECT (id,provider_id,holder_name,holder_document,account_label,external_account_id,enabled,access_state,created_at,updated_at) ON public.internet_provider_accounts TO authenticated;
CREATE OR REPLACE FUNCTION public.internet_dispatch_collection(p_scope text,p_provider_id uuid,p_account_id uuid,p_request_key uuid,p_actor_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_run uuid; v_count integer; BEGIN IF auth.role() <> 'service_role' OR p_actor_id IS NULL OR NOT public.has_role(p_actor_id,'super_admin') THEN RAISE EXCEPTION 'Not authorized'; END IF; IF p_scope NOT IN ('all','provider','account') OR p_request_key IS NULL OR (p_scope='provider' AND p_provider_id IS NULL) OR (p_scope='account' AND p_account_id IS NULL) OR (p_scope='all' AND (p_provider_id IS NOT NULL OR p_account_id IS NOT NULL)) OR (p_scope='provider' AND p_account_id IS NOT NULL) OR (p_scope='account' AND p_provider_id IS NOT NULL) THEN RAISE EXCEPTION 'Invalid scope'; END IF; PERFORM pg_advisory_xact_lock(hashtext('internet_collection_dispatch')); SELECT id INTO v_run FROM public.internet_collection_runs WHERE request_key=p_request_key; IF v_run IS NOT NULL THEN RETURN v_run; END IF; SELECT r.id INTO v_run FROM public.internet_collection_runs r JOIN public.internet_collection_jobs j ON j.run_id=r.id JOIN public.internet_provider_accounts a ON a.id=j.account_id WHERE r.state IN ('queued','running') AND j.state NOT IN ('completed','error','intervention_required') AND a.enabled AND (p_scope='all' OR (p_scope='provider' AND a.provider_id=p_provider_id) OR (p_scope='account' AND a.id=p_account_id)) LIMIT 1; IF v_run IS NOT NULL THEN RETURN v_run; END IF; INSERT INTO public.internet_collection_runs(scope,provider_id,account_id,request_key,requested_by) VALUES(p_scope,p_provider_id,p_account_id,p_request_key,p_actor_id) RETURNING id INTO v_run; INSERT INTO public.internet_collection_jobs(run_id,account_id) SELECT v_run,a.id FROM public.internet_provider_accounts a JOIN public.internet_providers p ON p.id=a.provider_id WHERE a.enabled AND a.access_state='ready' AND a.credential_ref IS NOT NULL AND p.enabled AND (p_scope='all' OR (p_scope='provider' AND p.id=p_provider_id) OR (p_scope='account' AND a.id=p_account_id)); GET DIAGNOSTICS v_count=ROW_COUNT; UPDATE public.internet_collection_runs SET expected_accounts=v_count,state=CASE WHEN v_count=0 THEN 'not_configured' ELSE 'queued' END,finished_at=CASE WHEN v_count=0 THEN now() ELSE NULL END WHERE id=v_run; INSERT INTO public.internet_audit_events(run_id,actor_id,actor_type,event_type,entity_type,entity_id,safe_details) VALUES(v_run,p_actor_id,'admin','collection_requested','run',v_run,jsonb_build_object('scope',p_scope,'expected_accounts',v_count)); RETURN v_run; END $$;